import numpy as np

def sigmoid(z):
    z = np.clip(z, -500, 500)
    return 1.0 / (1.0 + np.exp(-z))

def fit_logistic(X, y, lr=0.1, steps=3000):
    n, d = X.shape
    W = np.zeros(d)
    b = 0.0
    losses = []
    for _ in range(steps):
        p = sigmoid(X @ W + b)
        pc = np.clip(p, 1e-12, 1 - 1e-12)
        losses.append(float(-np.mean(y * np.log(pc) + (1 - y) * np.log(1 - pc))))
        err = p - y
        W -= lr * (X.T @ err) / n
        b -= lr * np.mean(err)
    return W, b, losses

def predict(X, W, b):
    return (sigmoid(X @ W + b) >= 0.5).astype(int)

